'use strict';
const assert=require('node:assert/strict'),{createHash}=require('node:crypto');
const {declaredCases,budget,summarize}=require('./ragDefenseAlignmentCohort');
const sha=s=>createHash('sha256').update(s).digest('hex');
const MODEL='llama3.1:8b',DIGEST='46e0c10c039e019119339687c3c1757cc81b9da49709a3b3924863ba87ca666e';
async function readRaw(response){const reader=response.clone().body.getReader();const chunks=[];let bytes=0;try{for(;;){const item=await reader.read();if(item.done)break;bytes+=item.value.byteLength;if(bytes>4*1024*1024)throw Error('Cohort transport response exceeds limit');chunks.push(Buffer.from(item.value));}return Buffer.concat(chunks).toString('utf8');}catch(e){await Promise.allSettled([reader.cancel(e),response.body.cancel(e)]);throw e;}finally{reader.releaseLock();}}
async function run(d){
 const {owner,upload,bound,coordinator,aiService,getRagSystemPrompt,completionService,migration,runtime,progress,evidence,save,setCall}=d;
 const declared=declaredCases(require('../../tests/release-inputs/rag-defense-alignment-cohort-design-2026-09-27.json')),limits=budget(),nativeFetch=global.fetch,lifetime=new AbortController();let current,phase,timer;
 evidence.declaredTaskSha256=sha(declared[0].question);evidence.cases=declared.map(entry=>({...entry,objectiveId:entry.objective}));evidence.cohort='rag-defense-alignment-v1';evidence.semanticAcceptance=false;evidence.transportCalls=[];
 const tags=await(await nativeFetch('http://127.0.0.1:11434/api/tags',{signal:AbortSignal.timeout(5000)})).json();assert.equal(tags.models.find(x=>x.name===MODEL)?.digest,DIGEST);evidence.model={name:MODEL,digest:DIGEST};
 global.fetch=async(url,options={})=>{const target=new URL(typeof url==='string'?url:url.url||String(url));assert.equal(target.origin,'http://127.0.0.1:11434');assert(['/api/chat','/api/show','/api/tags'].includes(target.pathname));
  let row;if(target.pathname==='/api/chat'){assert(current&&phase);limits.admit(current.id,phase);row={caseId:current.id,phase,status:'pending',request:JSON.parse(options.body)};assert.equal(row.request.model,MODEL);evidence.transportCalls.push(row);save();}
  try{const response=await nativeFetch(url,{...options,signal:AbortSignal.any([lifetime.signal,...(options.signal?[options.signal]:[]),AbortSignal.timeout(120000)])});if(row){row.httpStatus=response.status;row.raw=await readRaw(response);row.sha256=sha(row.raw);row.status='returned';save();}return response;}catch(e){if(row){row.status='failed';row.errorCode=e.code||e.name;save();}throw e;}
 };
 setCall(async(kind,messages,tools,options,configured)=>{phase=kind;const row={caseId:current.id,kind,status:'pending',messages};evidence.calls.push(row);save();try{const result=await configured.chat(messages,tools,{...options,signal:AbortSignal.any([lifetime.signal,...(options.signal?[options.signal]:[])])});row.provider=result.provider;row.model=result.model;row.rawResponse=result.response;row.responseSha256=sha(result.response||'');row.status='returned';save();return result;}catch(e){row.status='failed';row.errorCode=e.code||e.name;save();throw e;}finally{phase=null;}});
 try{
  const siblingOwner=await owner(),sibling=await upload(siblingOwner,'Sibling policy remains retained.');const siblingBefore=(await migration.query('SELECT to_jsonb(d) AS row FROM workshop_rag.documents d WHERE owner_id=$1',[siblingOwner.ownerId])).rows;
  timer=setTimeout(()=>lifetime.abort(Error('Declared cohort deadline')),1200000);
  for(const entry of declared){current=evidence.cases.find(c=>c.id===entry.id);save();if(lifetime.signal.aborted){current.notAttempted='cohort_deadline';save();continue;}
   const caseSignal=AbortSignal.any([lifetime.signal,AbortSignal.timeout(150000)]);let o;try{caseSignal.throwIfAborted();o=await owner();caseSignal.throwIfAborted();const documentId=await upload(o,entry.text,{timeoutMs:150000,signal:caseSignal});current.documentId=documentId;await coordinator.run(o.ownerId,{timeoutMs:150000,signal:caseSignal},async execution=>{current.runId=execution.runId;const result=await require('../../server/agent-runtime/ragQueryGraph').runRagQueryGraph({userKey:String(o.ownerId),sessionId:documentId,question:entry.question,active_objective:entry.objective,platformUserId:o.ownerId},{durableRagStore:{search:async args=>{const r=await bound(o,execution).search(args);current.retrievalReceipts??=[];current.retrievalReceipts.push(r.receipt);save();return r;}},aiService,getRagSystemPrompt,markRagObjectiveComplete:async()=>{},execution,completionService});current.answer=result.raw_model_answer;current.answerSha256=sha(current.answer);current.retrievedChunks=result.retrieved_chunks;current.judgments=result.judgments;current.completedObjectiveIds=result.completedObjectiveIds;});
   }catch(e){current.failure={name:e.name,code:e.code||null};}
   try{if(current.runId){current.persistedJudgments=(await migration.query('SELECT user_id,workshop_key,objective_id,generation,verdict,disposition,evidence_digest FROM workshop_platform.objective_judgments WHERE run_id=$1',[current.runId])).rows;current.effects=(await migration.query('SELECT status,count(*)::int AS count FROM graph_runtime.effects WHERE run_id=$1 GROUP BY status',[current.runId])).rows;}
   if(o){current.ownerId=o.ownerId;const judgment=current.persistedJudgments?.[0];if(judgment){assert.equal(judgment.user_id,o.ownerId);assert.equal(judgment.objective_id,entry.objective);assert.equal(judgment.workshop_key,'indirect_prompt_injection');current.completionReadback=await progress.getObjectiveCompletionState(o.ownerId,judgment.workshop_key,entry.objective,{expectedGeneration:judgment.generation});assert.equal(current.completionReadback.completed,current.completedObjectiveIds?.includes(entry.objective)||false);}const history=(await migration.query('SELECT to_jsonb(j) AS row FROM workshop_platform.objective_judgments j WHERE user_id=$1 ORDER BY evaluation_id',[o.ownerId])).rows;await coordinator.reset(o.ownerId,async execution=>{const sources=require('../../server/database/postgres/workshopRagRepository').createWorkshopRagRepository(runtime,{checkCurrent:()=>execution.check(),checkResetCurrent:()=>execution.check()});await sources.retire({...o,family:'RAG',slot:'current',graphGeneration:String(execution.durableGeneration),resourceGeneration:'0'},{operationId:require('node:crypto').randomUUID()});await progress.resetWorkshopProgress(o.ownerId,'indirect_prompt_injection');});assert.deepEqual((await migration.query('SELECT to_jsonb(j) AS row FROM workshop_platform.objective_judgments j WHERE user_id=$1 ORDER BY evaluation_id',[o.ownerId])).rows,history);}
   }catch(e){current.cleanupFailure={name:e.name,code:e.code||null};current.failure??={name:'PostCaseVerificationFailed',code:null};}save();
  }
  assert.deepEqual((await migration.query('SELECT to_jsonb(d) AS row FROM workshop_rag.documents d WHERE owner_id=$1',[siblingOwner.ownerId])).rows,siblingBefore);await coordinator.run(siblingOwner.ownerId,{},async e=>assert.equal((await bound(siblingOwner,e).state()).documentId,sibling));
  for(const c of evidence.cases){c.actualTransportCalls=evidence.transportCalls.filter(r=>r.caseId===c.id);if(!c.actualTransportCalls.length)c.failure??={name:'MissingActualTransport',code:null};}evidence.actualTransportCount=limits.total;const finalTags=await(await nativeFetch('http://127.0.0.1:11434/api/tags',{signal:AbortSignal.timeout(5000)})).json();assert.equal(finalTags.models.find(x=>x.name===MODEL)?.digest,DIGEST);evidence.modelDigestStable=true;evidence.summary=summarize(evidence.cases);evidence.status=evidence.summary.technicalComplete?'technical-complete-manual-review-needed':'incomplete';save();
 }finally{clearTimeout(timer);lifetime.abort();global.fetch=nativeFetch;setCall(null);save();}
}
module.exports={run,readRaw};
